CREATE DEFINER=`root`@`localhost` FUNCTION `generate_employee_id` () RETURNS VARCHAR(20) CHARSET utf8mb4 BEGIN
    DECLARE next_id INT;
    DECLARE new_emp_id VARCHAR(20);
    
    -- Get the next auto-increment value from the users table
    SELECT IFNULL(MAX(id), 0) + 1 INTO next_id FROM users;
    
    -- Create the formatted ID (e.g., EMP001, EMP002)
    SET new_emp_id = CONCAT('EMP', LPAD(next_id, 3, '0'));
    
    RETURN new_emp_id;
END$$

